    {"교리": "영원한 작정(예정)", "설명": "영생의 약속이 영원한 때 전부터 있었다는 것은 구원이 하나님의 영원한 계획 안에 있음을 뜻한다. 이는 칭의와 영화까지 포함하는 완전한 구원의 작정이다", "관련구절": "엡 1:4, 딤후 1:9, 롬 8:29-30, 벧전 1:20"}
