    {"영어원문": "God that cannot lie — the truth of God is the foundation of our hope; his word and his oath are two immutable things.", "한국어번역": "거짓이 없으신 하나님 - 하나님의 진실하심이 우리 소망의 기초이다. 그의 말씀과 그의 맹세는 변할 수 없는 두 가지이다.", "핵심통찰": "소망의 기초는 거짓이 없으신 하나님의 성품이다"}
