    {"상황": "구원의 확신이 흔들리는 성도", "성경원리": "구원은 인간의 결단이 아니라 영원 전 하나님의 작정에 근거한다. 거짓이 없으신 분의 약속은 변하지 않는다", "실제적용": "구원의 확신을 자신의 감정이나 행위가 아닌 하나님의 약속과 성품에 근거하여 회복하도록 돕라"}
