    {"원어": "χάρις καὶ εἰρήνη (카리스 카이 에이레네)", "의미_문법": "은혜와 평강 - 명사 병렬. 바울 서신의 전형적 인사", "설교포인트": "은혜가 먼저이고 평강이 뒤따른다. 하나님의 은혜를 경험한 자만이 참된 평강을 누린다"}
