    {"항목": "같은 믿음의 의미", "내용": "바울이 '같은 믿음을 따라'라고 한 것은 사도와 이방인 개종자 사이에 믿음의 동등함을 선언하는 것이다. 유대인과 이방인의 차별 없이 동일한 복음을 공유한다", "목회적활용": "교회 안에서 직분이나 배경의 차이가 있어도 믿음의 질에는 차등이 없다. 이것이 복음적 평등이다"}
