    {"대지": "1대지: 의도적 파송 (떨어뜨려 둔 이유)", "내용": "바울은 디도를 우연히 남긴 것이 아니라 의도적으로 파송했다. 어려운 사역지에 가장 신뢰하는 동역자를 보내는 것이 사도적 전략이다", "예화_적용": "가장 어려운 수술에 가장 유능한 의사를 보내듯 하나님은 가장 어려운 곳에 가장 적합한 일꾼을 보내신다"},
    {"대지": "2대지: 부족한 일을 바로잡고 (교정의 사명)", "내용": "교회에는 바로잡아야 할 부족함이 있다. 이를 방치하지 않고 교정하는 것이 목회자의 책임이다", "예화_적용": "정원사가 잡초를 뽑고 가지를 다듬듯 목회자는 교회의 부족한 부분을 바로잡아야 한다"},
    {"대지": "3대지: 각 성에 장로를 세우라 (지도자 세움)", "내용": "교회 질서의 핵심은 각 지역에 합당한 장로를 세우는 것이다. 장로의 자질이 교회의 방향을 결정한다", "예화_적용": "기둥이 튼튼해야 건물이 서듯 장로가 건강해야 교회가 건강하다"},
    {"대지": "결론", "내용": "교회는 자연 성장만으로 건강해지지 않는다. 부족한 것을 바로잡고 합당한 지도자를 세우는 의도적 노력이 필요하다. 이것이 바울이 디도에게 맡긴 사명이다", "예화_적용": "방치된 정원은 아무리 좋은 토양이라도 황폐해진다. 돌봄과 질서가 건강한 공동체의 비결이다"}
