    {"대지": "3대지: 할례당의 위험 (복음의 변질)", "내용": "할례당은 복음에 율법의 행위를 더하려 한다. 은혜에 행위를 추가하는 것은 복음의 본질을 훼손하는 것이다", "예화_적용": "순금에 불순물을 섞으면 가치가 떨어진다. 복음의 순수한 은혜에 인간의 행위를 더하면 복음이 변질된다"},
    {"대지": "결론", "내용": "교회는 거짓 교사를 분별하고 대항해야 한다. 바른 교훈에 굳게 서서 은혜의 복음을 지키는 것이 장로와 모든 성도의 책임이다", "예화_적용": "면역 체계가 약하면 질병에 걸리듯 교리적 분별력이 없으면 거짓 교훈에 감염된다. 말씀이 우리의 영적 면역 체계이다"}
