    {"항목": "더러운 이를 위한 가르침", "내용": "그레데의 거짓 교사들은 유대적 전설과 율법적 규정을 가르치면서 대가를 요구했다. 이들의 진정한 동기는 영혼 구원이 아닌 물질적 이득이었다", "목회적활용": "사역의 동기를 정직하게 점검해야 한다. 영혼을 위한 것인가 주머니를 위한 것인가"}
