    {"원어": "ἀδόκιμοι (아도키모이)", "의미_문법": "버리운(부적격한) - 형용사 남성 복수 주격. 시험에 통과하지 못한, 불합격한", "설교포인트": "아도키모스는 금속의 품질 검사에서 불합격한 것을 뜻한다. 선한 일에 버리운 자는 하나님의 검증에 합격하지 못한 자이다"}
