    {"항목": "세 가지 정죄", "내용": "바울은 거짓 교사를 세 가지로 정죄한다. 가증한(하나님 앞에 역겨운), 복종치 아니하는(권위를 거부하는), 선한 일에 버리운(쓸모없는). 이 삼중 정죄는 그들의 영적 상태의 심각성을 보여준다", "목회적활용": "경건의 외형은 있으나 능력이 없는 삶(딤후 3:5)은 가장 위험한 자기 기만이다"}
