    {"교리": "여성의 교육적 사명", "설명": "바울은 늙은 여자에게 '선한 것을 가르치는 자'(칼로디다스칼루스)의 역할을 부여한다. 이는 공적 강단의 교육이 아닌 삶을 통한 멘토링이다. 여성의 교육적 사명이 분명히 있다", "관련구절": "딛 2:4-5, 딤후 1:5, 딤후 3:15, 잠 31:26"}
