    {"교리": "복종과 자유", "설명": "기독교적 자유는 사회적 질서의 파괴가 아닌 그 안에서의 내적 해방이다. 종이 기쁜 마음으로 섬기는 것은 억압이 아니라 그리스도의 종으로서의 자발적 선택이다", "관련구절": "갈 5:13, 고전 7:22, 빌 2:5-8, 롬 6:18"}
