    {"상황": "선한 일에 대한 동기가 약해진 성도", "성경원리": "선한 일에 열심하는 것은 구속의 목적이다. 의무가 아닌 구속받은 감사의 응답으로 선을 행한다", "실제적용": "율법적 의무감이 아닌 은혜에 대한 감사에서 동기를 찾도록 돕고 구체적인 선행의 기회를 함께 찾아보라"}
