    {"대지": "서론", "내용": "디도서 2장은 이 강력한 명령으로 끝난다. 바른 교훈(1-10절)과 은혜의 교리(11-14절)를 담대히 말하고 권면하며 책망하라. 업신여김을 받지 말라", "예화_적용": "대사가 본국의 권위로 말하듯 목회자는 하나님의 권위로 말한다. 대사의 권위는 대사 자신이 아닌 파견국에서 나온다"},
    {"대지": "1대지: 말하라 (진리의 선포)", "내용": "말하라(랄레이)는 복음의 진리를 공개적으로 선포하라는 명령이다. 11-14절의 은혜와 구속의 복음을 담대히 전하라", "예화_적용": "파수꾼이 적의 침입을 알리듯 목회자는 복음의 진리를 선포해야 한다. 침묵은 직무유기이다"},
    {"대지": "2대지: 권면하고 책망하라 (적용과 교정)", "내용": "권면(파라칼레오)은 격려하며 촉구하는 것이고 책망(엘렝코)은 잘못을 바로잡는 것이다. 이 둘이 함께 가야 건강한 목회가 된다", "예화_적용": "의사가 약을 처방하면서 동시에 나쁜 생활 습관을 고치라고 하듯 목회자는 격려와 교정을 동시에 해야 한다"},
    {"대지": "3대지: 업신여김을 받지 말라 (권위의 유지)", "내용": "업신여김을 받지 않는 방법은 강압이 아닌 거룩한 삶과 말씀에 근거한 담대함이다. 권위는 위에서 부여받고 삶으로 유지된다", "예화_적용": "장군의 권위는 계급장에서 나오지만 부하의 존경은 장군의 인격에서 나온다. 목회 권위도 위임과 인격 모두 필요하다"},
    {"대지": "결론", "내용": "목회자여 담대히 말하고 권면하고 책망하라. 권위는 하나님에게서 오며 삶의 모범으로 유지된다. 업신여김을 두려워하지 말고 맡겨진 사명을 충실히 수행하자", "예화_적용": "촛불은 바람을 두려워하지 않는다. 빛나는 것이 촛불의 존재 이유이기 때문이다. 목회자도 두려워하지 말고 빛으로 서라"}
