    {"원어": "πραΰτητα (프라위테타)", "의미_문법": "온유함 - 명사 여성 단수 대격. 부드러움, 겸손한 힘", "설교포인트": "프라위테스(온유)는 통제된 힘이다. 힘이 없어서가 아니라 힘을 다스릴 줄 아는 성품이다. 모세도 '온유한 자'로 불렸다(민 12:3)"}
