    {"항목": "모든 사람에게", "내용": "이 온유함과 관용은 교회 안의 형제에게만이 아니라 '모든 사람'(판타스 안드로푸스)에게 보여야 한다. 믿지 않는 이웃, 심지어 대적자에게도 이 성품이 요구된다", "목회적활용": "기독교적 덕목은 교회 안에서만이 아니라 세상의 모든 사람을 향해야 한다"}
