    {"구분": "돌아온 탕자", "내용": "탕자가 돼지 먹이로 배를 채우려 했던 비참한 상태(눅 15:16)는 정욕에 종노릇하는 인간의 모습을 그린다", "그리스도연결": "아버지는 탕자를 기다리셨듯 하나님은 우리의 돌아옴을 기다리시며 최상의 것으로 맞아주신다"}
