    {"대지": "서론", "내용": "3절의 처참한 타락 목록 후에 4절의 '그러나'가 모든 것을 바꾼다. 어리석고 타락하고 미워하던 우리에게 하나님의 자비와 사랑이 나타났다. 이것이 복음이다", "예화_적용": "사형 선고를 받은 죄수에게 '그러나 사면한다'라는 말보다 더 기쁜 소식은 없다. 복음의 '그러나'가 바로 그것이다"},
    {"대지": "1대지: 자비 - 크레스토테스 (하나님의 성품)", "내용": "크레스토테스는 하나님의 따뜻한 인자하심이다. 심판하실 수 있는 분이 자비를 베푸신다. 이것이 하나님의 놀라운 성품이다", "예화_적용": "엄한 판사가 법정에서 죄수를 용서할 때 모든 사람이 놀란다. 의로우신 하나님이 죄인을 자비로 대하실 때 천사들도 놀란다"},
    {"대지": "2대지: 사람 사랑하심 - 필란드로피아 (사랑의 대상)", "내용": "필란드로피아는 사람을 향한 사랑이다. 사랑받을 자격 없는 인간을 하나님이 먼저 사랑하셨다. 이것이 은혜이다", "예화_적용": "어머니가 아무리 잘못한 자녀라도 사랑하듯 하나님은 타락한 인간을 포기하지 않으시고 사랑하신다"},
    {"대지": "3대지: 나타날 때에 - 에피파네이아 (은혜의 현현)", "내용": "자비와 사랑이 추상적 개념이 아니라 역사 속에 '나타났다.' 그리스도의 성육신이 하나님의 자비와 사랑의 구체적 현현이다", "예화_적용": "편지로만 사랑을 전하던 아버지가 직접 찾아오는 것은 차원이 다른 사랑의 표현이다. 하나님이 직접 오신 것이 은혜의 정점이다"},
    {"대지": "결론", "내용": "3절의 어둠 후에 4절의 빛이 온다. 타락 후에 자비가, 미움 후에 사랑이, 종노릇 후에 자유가 나타났다. 이 '그러나'가 우리 인생의 전환점이다", "예화_적용": "겨울이 아무리 길어도 봄은 반드시 온다. 인간의 타락이 아무리 깊어도 하나님의 자비는 반드시 나타난다"}
