    {"대지": "서론", "내용": "5절은 디도서 전체에서 가장 풍성한 구원론이 담긴 절이다. 구원의 부정적 근거(인간의 행위가 아님)와 긍정적 근거(하나님의 긍휼)와 구원의 방법(중생과 성령의 갱신)이 한 절에 압축되어 있다", "예화_적용": "다이아몬드가 작은 크기에 엄청난 가치를 담고 있듯 이 한 절에 구원론의 핵심이 모두 담겨 있다"},
    {"대지": "1대지: 의로운 행위로 말미암지 아니하고 (부정적 근거)", "내용": "구원의 근거에서 인간의 행위가 완전히 배제된다. 가장 의로운 행위라도 구원의 조건이 될 수 없다. 이것이 복음과 종교의 결정적 차이이다", "예화_적용": "바닷물로 갈증을 해결할 수 없듯 인간의 의로운 행위로 구원의 갈증을 해결할 수 없다. 원천이 다르다"},
    {"대지": "2대지: 오직 그의 긍휼하심을 좇아 (긍정적 근거)", "내용": "구원의 유일한 근거는 하나님의 긍휼이다. 긍휼(엘레오스)은 비참한 자를 불쌍히 여기시는 하나님의 마음이다", "예화_적용": "의사가 병든 자에게 가듯 하나님의 긍휼은 비참한 자에게 향한다. 자격이 아닌 필요가 긍휼을 부른다"},
    {"대지": "3대지: 중생의 씻음과 성령의 새롭게 하심 (구원의 방법)", "내용": "중생의 씻음은 옛 것의 청산이고 성령의 새롭게 하심은 새 것의 시작이다. 씻음과 갱신이 함께 구원을 이룬다", "예화_적용": "집을 리모델링할 때 먼저 낡은 것을 철거하고 새 것으로 채우듯 중생은 옛 것을 씻고 성령은 새 것으로 채우신다"},
    {"대지": "결론", "내용": "구원은 오직 하나님의 긍휼에서 시작되어 성령의 역사로 완성된다. 인간의 행위가 아닌 하나님의 은혜가 구원의 유일한 근거이다. 이 복음을 믿고 감사하며 살자", "예화_적용": "선물은 받는 자의 자격이 아닌 주는 자의 사랑에서 온다. 구원은 하나님의 사랑의 선물이다"}
