    {"영어원문": "Heirs according to the hope of eternal life — not yet in full possession, but certain heirs, having a well-grounded hope.", "한국어번역": "영생의 소망을 따라 후사 - 아직 완전한 소유는 아니지만 확실한 상속자이며 확고한 근거 있는 소망을 가진 자이다.", "핵심통찰": "아직 완성은 아니지만 확실한 상속자이다"}
