    {"원어": "παραιτοῦ (파라이투)", "의미_문법": "멀리하라(거부하라) - 동사 명령 현재 중간태 2인칭 단수. 사양하다, 피하다", "설교포인트": "파라이테오마이는 '거부하다, 피하다'라는 뜻이다. 훈계 후에도 돌이키지 않으면 관계를 끊어야 한다. 이것은 교회를 보호하기 위한 필수적 조치이다"}
