    {"항목": "10-11절의 연결", "내용": "10절의 '멀리하라'는 명령의 이유가 11절에서 설명된다. 이런 자는 이미 부패하여 스스로 정죄한 상태에 있기 때문에 더 이상의 훈계가 무익하다는 것이다", "목회적활용": "교회가 이단자를 멀리하는 것은 냉정함이 아니라 이미 스스로 정죄한 현실을 인정하는 것이다"}
