    {"영어원문": "When a man has been twice admonished and yet persists, there is no more to be done but to leave him to himself.", "한국어번역": "두 번 훈계를 받고도 여전히 고집하면 더 이상 할 것은 없고 그를 스스로에게 맡기는 것밖에 없다.", "핵심통찰": "충분한 경고 후에도 변하지 않으면 더 이상의 개입은 무익하다"}
