    {"새찬송가": "265", "통일찬송가": "230", "제목": "교회의 참 되신 터는", "선정이유": "교회의 순결과 보호를 위한 기도를 담는다"},
    {"새찬송가": "338", "통일찬송가": "369", "제목": "주 예수 내가 알기 전", "선정이유": "부패에서 돌아와 주님을 만난 변화를 고백한다"},
    {"새찬송가": "305", "통일찬송가": "362", "제목": "나의 갈 길 다 가도록", "선정이유": "진리에서 벗어나지 않겠다는 결단을 표현한다"}
