    {"구분": "다윗의 용사들", "내용": "다윗에게 충성된 용사들이 있었듯(삼하 23장) 바울에게도 충성된 동역자들이 있었다. 위대한 지도자 뒤에는 충성된 동역자가 있다", "그리스도연결": "그리스도는 교회에 사도, 선지자, 목사, 교사를 선물로 주셨다(엡 4:11)"}
