    {"대지": "서론", "내용": "교리적 가르침을 마친 바울은 실제적 사역 지시로 돌아온다. 동역자를 보내고 디도를 부르는 구체적 계획은 복음 사역의 전략성과 협력의 중요성을 보여준다", "예화_적용": "교향곡은 한 악기로 연주되지 않는다. 복음 사역도 여러 동역자의 조화로운 협력이 필요하다"},
    {"대지": "1대지: 동역자 파견 (사역의 연속성)", "내용": "아데마나 두기고를 보내어 디도의 사역을 인수하게 한다. 사역은 한 사람에게 의존하지 않고 연속성을 가져야 한다", "예화_적용": "릴레이 경주에서 바통을 넘기듯 사역의 바통을 다음 주자에게 잘 넘기는 것이 중요하다"},
    {"대지": "2대지: 급히 오라 (동역의 필요)", "내용": "바울은 디도를 곁에 필요로 한다. 위대한 사도도 혼자가 아닌 함께 사역하기를 원한다. 고독한 사역은 건강하지 않다", "예화_적용": "전선의 장군도 참모가 필요하듯 사역의 최전선에서도 동역자가 필요하다"},
    {"대지": "3대지: 겨울을 지내기로 작정하였노라 (전략적 계획)", "내용": "바울은 구체적 계획을 세운다. 어디서 겨울을 나고 누구를 어디로 보낼지 전략적으로 사고한다. 영적이면서도 실제적인 리더십이다", "예화_적용": "좋은 농부는 계절에 맞는 계획을 세운다. 좋은 사역자도 시간과 자원에 맞는 전략을 세운다"},
    {"대지": "결론", "내용": "복음 사역은 협력과 계획과 전략이 필요하다. 혼자가 아닌 함께, 즉흥이 아닌 계획적으로 사역하자. 동역자를 세우고 연속성을 확보하는 것이 건강한 사역이다", "예화_적용": "한 그루의 나무보다 숲이 더 건강하듯 함께 하는 사역이 혼자 하는 사역보다 건강하고 지속 가능하다"}
