    {"항목": "필요한 것을 준비하는 좋은 일", "내용": "여기서 '필요한 것을 준비하는'(에이스 타스 아낭카이아스 크레이아스)은 13절의 세나와 아볼로에 대한 지원뿐 아니라 일반적으로 필요한 곳에 물질적 도움을 제공하는 것을 포함한다", "목회적활용": "선한 일은 추상적이 아니라 구체적 필요에 응답하는 것이다"}
