    {"대지": "3대지: 열매 없는 자가 되지 말라 (결과의 점검)", "내용": "그리스도인은 열매로 검증된다. 열매 없는 신앙은 진정한 신앙이 아니다. 정기적으로 삶의 열매를 점검해야 한다", "예화_적용": "농부가 가을에 수확을 점검하듯 성도도 자기 삶의 열매를 정기적으로 돌아보아야 한다"},
    {"대지": "결론", "내용": "선한 일에 힘쓰기를 배워 열매 있는 삶을 살자. 이것은 디도서 전체의 핵심 메시지이며 은혜에 대한 합당한 응답이다", "예화_적용": "은혜의 비를 맞은 땅이 풍성한 열매를 맺듯 은혜받은 삶이 선한 열매를 맺어야 한다"}
